        var disconnected=CityCoreIndustrySession.Create(startAtWork:true);disconnected.Transport.RemoveRoad(2);disconnected.Advance(2);Check(disconnected.Transport.ActiveCount==0&&disconnected.City.Goods(1)>0&&disconnected.City.Factory(1).salesRevenue==0,"Unreachable request debited stock");
        var interrupted=CityCoreIndustrySession.Create(startAtWork:true);interrupted.Advance(2);var task=interrupted.Transport.Vehicles.First();int cargo=task.Task.Cargo;Point before=interrupted.Transport.Position(task);interrupted.Transport.RemoveRoad(1);interrupted.Advance(.05);Check(task.status==VehicleStatus.Stranded&&task.Task.Cargo==cargo&&Point.Distance(before,interrupted.Transport.Position(task))<1e-8,"Road interruption lost cargo/position");var loaded=CityCoreSave.Read(CityCoreSave.Write(interrupted));Check(loaded.Transport.Vehicles.Sum(v=>v.Task.Cargo)==interrupted.Transport.Vehicles.Sum(v=>v.Task.Cargo),"Interrupted saved cargo lost");
        var empty=CityCoreIndustrySession.Create(startAtWork:true);foreach(var worker in empty.City.Citizens)worker.atWork=false;empty.Advance(3);Check(empty.City.Factory(1).produced==0&&empty.Transport.ActiveCount==0,"Jobs alone produced goods");
        var busy=CityCoreIndustrySession.Create(startAtWork:true);busy.Advance(2);var busySave=CityCoreSave.Write(busy);bool refused=false;try{busy.CloseBuilding(2);}catch(CityRuleException){refused=true;}Check(refused&&busySave.SequenceEqual(CityCoreSave.Write(busy)),"Busy destination closure mutated cargo/business");refused=false;try{busy.CloseBuilding(1);}catch(CityRuleException){refused=true;}Check(refused&&busySave.SequenceEqual(CityCoreSave.Write(busy)),"Busy employer closure mutated attendance/payroll");
        var closed=CityCoreIndustrySession.Create();double companyCash=closed.City.Factory(1).cash;closed.CloseBuilding(1);var closedLoad=CityCoreSave.Read(CityCoreSave.Write(closed));closedLoad.Advance(.1);Check(closedLoad.SnapshotBusiness().retiredBuildings[0].industrial[0].cash==companyCash,"Closed idle business finance lost on load");closedLoad.Validate();
