    static void ResidentTests()
    {
        var session=CityCoreIndustrySession.Create();Check(session.City.Citizens.All(p=>!p.atWork&&p.location==3),"Default workers invented onsite attendance");session.Advance(.05);Check(session.Transport.ActiveCount==1&&session.Transport.Vehicles[0].Task.purpose==TransportPurpose.Work&&session.City.Factory(1).produced==0,"Departure did not use real empty passenger vehicle / produced before arrival");var person=session.City.Citizens.First(p=>p.tripId>0);var task=session.Transport.FindTaskVehicle(person.tripId);var observed=session.Residents.Observe(person.id);Check(observed.travelling&&observed.destination==1&&observed.x< -25,"Resident observation did not use real vehicle");Check(session.Simulation.RequestCommute(person.id,3,1)==null,"Resident got two simultaneous cars");
        session.Transport.SplitRoadAt(1,5);var restore=CityCoreSave.Read(CityCoreSave.Write(session));for(int i=0;i<220;i++){session.Advance(.05);restore.Advance(.05);session.Validate();Check(Convert.ToBase64String(CityCoreSave.Write(session))==Convert.ToBase64String(CityCoreSave.Write(restore)),"Resident saved in motion diverged");}Check(session.City.Citizens.All(p=>p.atWork&&p.lastCommute>0&&p.workedMinutes>0)&&session.City.Factory(1).sold>0,"Actual commuting did not cause labour/production/delivery");
        while(!session.Transport.Vehicles.Any(v=>v.Task.purpose==TransportPurpose.Home)&&session.Transport.Clock<40)session.Advance(.05);var returning=session.Transport.Vehicles.First(v=>v.Task.purpose==TransportPurpose.Home);double x=session.Transport.Position(returning).x;session.Advance(.05);Check(session.Transport.Position(returning).x<x&&returning.Task.Cargo==0,"Return trip did not actually travel west / carries invented goods");var returnLoad=CityCoreSave.Read(CityCoreSave.Write(session));for(int i=0;i<180;i++){session.Advance(.05);returnLoad.Advance(.05);}Check(Convert.ToBase64String(CityCoreSave.Write(session))==Convert.ToBase64String(CityCoreSave.Write(returnLoad)),"Return save differs");Check(session.City.Citizens.All(p=>!p.atWork&&p.tripId==0&&p.location==3),"Workers never returned home");
        int savings=session.City.society.families[0].savings;session.Advance(40);session.Validate();Check(session.City.day==2&&session.City.Citizens.Sum(p=>p.wagesPaid)>0&&session.City.society.families[0].savings>savings,"Actual employer wages did not reach household at day boundary");
        var blocked=CityCoreIndustrySession.Create();blocked.Transport.RemoveRoad(1);blocked.Advance(3);Check(blocked.Transport.ActiveCount==0&&blocked.City.Factory(1).produced==0&&blocked.City.Citizens.All(p=>p.location==3&&!p.atWork),"Broken commute still produced labour");
        var interrupted=CityCoreIndustrySession.Create();interrupted.Advance(.05);var rider=interrupted.City.Citizens.First(p=>p.tripId>0);var car=interrupted.Transport.FindTaskVehicle(rider.tripId);Point before=interrupted.Transport.Position(car);interrupted.Transport.RemoveRoad(1);interrupted.Advance(.05);interrupted.Validate();Check(car.status==VehicleStatus.Stranded&&rider.tripId==car.Task.id&&rider.location==-1&&!rider.atWork&&Point.Distance(before,interrupted.Transport.Position(car))<1e-7,"Cut road lost/teleported commuting citizen");CityCoreSave.Read(CityCoreSave.Write(interrupted)).Validate();
        interrupted.Transport.AddRoad(1,2,new[]{interrupted.Transport.JunctionPosition(1),new Point(-18,0,0),interrupted.Transport.JunctionPosition(2)},lanes:2);interrupted.Advance(.05);Check(car.status==VehicleStatus.Active&&car.Task.citizenId==rider.id&&rider.tripId==car.Task.id&&Point.Distance(before,interrupted.Transport.Position(car))<.7,"Repaired road did not recover same citizen/car without jump");interrupted.Advance(6);interrupted.Validate();Check(rider.atWork&&interrupted.City.Factory(1).produced>0,"Recovered commute did not resume actual labour");
    }
    static CommercialBuilding AsShop(this CityBuilding b)=>(CommercialBuilding)b;
    static void RoadEditingTests()
    {
        var s=CityGrowingGridFixture.Create();int id=s.Transport.Network.RoadIds.Max();Check(id>1,"Selected-road fixture only contains road 1");var geometry=s.Transport.Network.Centreline(id);var hit=geometry.Sample(geometry.Length/2);Check(s.Construction.PickRoad(hit)==id,"Road picker lost non-first logical identity");
        byte[] before=CityCoreSave.Write(s);for(int i=0;i<1000;i++)Check(s.Construction.PickRoad(hit)==id,"Warm road selection changed target");Check(before.SequenceEqual(CityCoreSave.Write(s)),"Road selection wrote simulation facts");
        var empty=CityCoreIndustrySession.CreateEmpty();empty.Simulation.Growth.Zoning.SetSurface((x,z)=>2);int a=empty.Transport.AddJunction(new Point(-40,2,0)),b=empty.Transport.AddJunction(new Point(40,2,0));var plan=empty.Transport.PlanRoad(a,b,new[]{empty.Transport.JunctionPosition(a),empty.Transport.JunctionPosition(b)});Check(empty.Construction.Commit(plan,out _),"Road fixture construction failed");int selected=empty.Transport.Network.RoadIds.Single(),money=empty.City.money;double length=empty.Transport.Network.Centreline(selected).Length;
        int paid=empty.Construction.UpgradeRoad(selected,2,RoadDirection.Both);Check(paid==(int)Math.Ceiling(length*(40.0/3)-1e-6)&&empty.City.money==money-paid&&empty.Transport.Network.Settings(selected).lanes==2,"Selected widening failed identity/cost commit");int revision=empty.Transport.NetworkGeneration;money=empty.City.money;Check(empty.Construction.UpgradeRoad(selected,2,RoadDirection.Both)==0&&empty.Transport.NetworkGeneration==revision&&empty.City.money==money,"No-op upgrade rebuilt network or charged treasury");
        empty.Construction.UpgradeRoad(selected,2,RoadDirection.Forward);empty.Construction.UpgradeRoad(selected,2,RoadDirection.Backward);Check(empty.Transport.Network.Route(a,b)==null&&empty.Transport.Network.Route(b,a)!=null,"Selected direction/reverse did not change real traversal");var loaded=CityCoreSave.Read(CityCoreSave.Write(empty));Check(loaded.Transport.Network.Settings(selected).direction==RoadDirection.Backward,"Edited road direction lost in save");
        before=CityCoreSave.Write(empty);bool rejected=false;try{empty.Construction.UpgradeRoad(99999,1,RoadDirection.Both);}catch(CityRuleException e){rejected=e.Key=="road.edit_missing";}Check(rejected&&before.SequenceEqual(CityCoreSave.Write(empty)),"Missing selection partially changed road/treasury");money=empty.City.money;empty.Construction.RemoveRoad(selected);Check(!empty.Transport.Network.ContainsRoad(selected)&&empty.City.money==money-40,"Selected demolition did not charge exactly once");empty.Validate();
        var occupied=CityCoreIndustrySession.Create();occupied.Advance(.05);var actor=occupied.Transport.Vehicles[0];var point=occupied.Transport.Position(actor);int task=actor.Task.id;before=CityCoreSave.Write(occupied);rejected=false;try{occupied.Construction.UpgradeRoad(1,2,RoadDirection.Backward);}catch(InvalidOperationException){rejected=true;}Check(rejected&&before.SequenceEqual(CityCoreSave.Write(occupied)),"Occupied lane reversal moved actors or charged on rejection");money=occupied.City.money;occupied.Construction.RemoveRoad(1);Check(occupied.City.money==money-40&&actor.status==VehicleStatus.Stranded&&actor.Task.id==task&&Point.Distance(point,occupied.Transport.Position(actor))<1e-8,"Selected demolition lost/teleported real commuting person");CityCoreSave.Read(CityCoreSave.Write(occupied)).Validate();
        var blocked=CityCoreIndustrySession.CreateEmpty();blocked.Simulation.Growth.Zoning.SetSurface((x,z)=>2);a=blocked.Transport.AddJunction(new Point(-40,2,0));b=blocked.Transport.AddJunction(new Point(40,2,0));blocked.Construction.Commit(blocked.Transport.PlanRoad(a,b,new[]{blocked.Transport.JunctionPosition(a),blocked.Transport.JunctionPosition(b)}),out _);var lot=new CommercialBuilding{id=1,x=0,z=2.4f,width=2,depth=2,groundY=2};Check(blocked.Simulation.Growth.Zoning.CanPlace(lot),"Obstruction fixture already overlaps narrow pavement");blocked.Entities.AddBuilding(lot);blocked.Transport.RegisterAccess(1,Network.LaneId(1,false),40);before=CityCoreSave.Write(blocked);rejected=false;try{blocked.Construction.UpgradeRoad(1,2,RoadDirection.Both);}catch(CityRuleException e){rejected=e.Key=="road.widen_obstructed";}Check(rejected&&before.SequenceEqual(CityCoreSave.Write(blocked)),"Widening consumed real building footprint or partially charged");var blockedLoad=CityCoreSave.Read(before);rejected=false;try{blockedLoad.Construction.UpgradeRoad(1,2,RoadDirection.Both);}catch(CityRuleException e){rejected=e.Key=="road.widen_obstructed";}Check(rejected&&before.SequenceEqual(CityCoreSave.Write(blockedLoad)),"Loaded building elevation/footprint failed widening protection");
        var rules=new GameDesignData();rules.finance.startingTreasury=1500;var poor=CityCoreIndustrySession.CreateEmpty(rules);a=poor.Transport.AddJunction(new Point(-40,2,0));b=poor.Transport.AddJunction(new Point(40,2,0));poor.Construction.Commit(poor.Transport.PlanRoad(a,b,new[]{poor.Transport.JunctionPosition(a),poor.Transport.JunctionPosition(b)}),out _);before=CityCoreSave.Write(poor);rejected=false;try{poor.Construction.UpgradeRoad(1,2,RoadDirection.Both);}catch(CityRuleException e){rejected=e.Key=="finance.insufficient_funds";}Check(rejected&&before.SequenceEqual(CityCoreSave.Write(poor)),"Unaffordable selected upgrade changed road or accounts");
        var heights=CityCoreIndustrySession.CreateEmpty();a=heights.Transport.AddJunction(new Point(0,2,0));b=heights.Transport.AddJunction(new Point(40,2,0));int c=heights.Transport.AddJunction(new Point(0,12,0)),d=heights.Transport.AddJunction(new Point(40,12,0));int low=heights.Transport.AddRoad(a,b,new[]{heights.Transport.JunctionPosition(a),heights.Transport.JunctionPosition(b)}),high=heights.Transport.AddRoad(c,d,new[]{heights.Transport.JunctionPosition(c),heights.Transport.JunctionPosition(d)});Check(heights.Construction.PickRoad(new Point(20,2,0),.7)==low&&heights.Construction.PickRoad(new Point(20,12,0),.7)==high&&heights.Construction.PickRoad(new Point(20,7,0),.7)==0,"Road selection collapsed stacked levels to XZ");
    }
    static void ObservationTests()
    {
        var s=CityCoreIndustrySession.Create();var family=s.City.society.families[0];s.Entities.AddResident(family.id,new CityResident{id=5,age=7,name="Child",canWork=false,location=3});
        ((ResidentialBuilding)s.Entities.Building(3)).housingUnits=8;var query=new CityCoreObservation(s);var a=family.people[0];var b=family.people[1];a.lastCommute=45;b.lastCommute=60;a.observedHome=b.observedHome=3;a.observedWork=b.observedWork=1;
        byte[] before=CityCoreSave.Write(s);var report=query.Read(3);Check(report.residents==5&&report.workforce==4&&report.employed==4&&report.families[0].commuteSamples==2&&report.families[0].averageCommute==52.5&&report.families[0].longestCommute==60,"Observation used children/household sum as employment/commute status");
        Check(report.occupied==1&&report.units==8&&report.problems==CityObservedProblem.None,"Ordinary vacancy was invented as a problem");
        Check(query.Pick(s.Entities.Building(3).x,s.Entities.Building(3).z)==3&&query.Read(999)==null,"Building selection did not use current real entity bounds/identity");
        for(int i=0;i<100;i++){query.Read(1);query.Read(2);query.Read(3);query.Issues();}Check(before.SequenceEqual(CityCoreSave.Write(s)),"Read-only city observation changed simulation/save");
        report.families[0].savings=-1;report.families[0].members[0].workplace=999;Check(family.savings>=0&&s.City.Workplace(a)==1,"Observation DTO exposed live economic/citizen state");
        s.Advance(.05);report=query.Read(3);var travelling=report.families[0].members.First(p=>p.task>0);var v=s.Transport.FindTaskVehicle(travelling.task);Check(travelling.vehicle==v.id&&travelling.destination==1&&travelling.origin==3,"Observation confused Task ID and Vehicle ID or missed actual destination");
        s.Transport.RemoveRoad(1);report=query.Read(3);Check((report.problems&CityObservedProblem.Road)!=0&&report.strandedCount>0&&report.families[0].members.First(p=>p.task>0).stranded,"Dynamic road interruption not observable");var clone=CityCoreSave.Read(CityCoreSave.Write(s));Check(new CityCoreObservation(clone).Read(3).strandedCount==report.strandedCount,"Restored observation read stale city/vehicle state");
        var quiet=CityGrowingGridFixture.Create();var empty=quiet.Entities.Buildings.First();var original=CityCoreSave.Write(quiet);var snapshot=new CityCoreObservation(quiet).Read(empty.id);Check(snapshot.jobs==0&&snapshot.filledJobs==0&&original.SequenceEqual(CityCoreSave.Write(quiet)),"Service observation invented employment or mutated utilities");
    }
    static void WasteTests()
    {
        var definition=new GameDesignData();definition.waste.payload=3;definition.waste.trucks=2;
        var s=CityGrowingGridFixture.Create(design:definition);int plantId=CityGrowingGridFixture.PlaceWasteFacility(s);
        var plant=(LandfillBuilding)s.Entities.Building(plantId);Check(s.Simulation.Waste.Generated==0&&s.Transport.Tasks.All(t=>t.purpose!=TransportPurpose.Service),"Waste appeared without actual activity");
        int outbound=0,returning=0,transitions=0;bool edited=false,savedOut=false,savedReturn=false,paused=false;
        var positions=new System.Collections.Generic.Dictionary<int,Point>();
        for(int i=0;i<16000;i++)
        {
            foreach(var v in s.Transport.Vehicles)if(v.Task.purpose==TransportPurpose.Service)positions[v.id]=s.Transport.Position(v);
            s.Advance(.05);
            foreach(var v in s.Transport.Vehicles.Where(v=>v.Task.purpose==TransportPurpose.Service).ToArray())
            {
                if(v.Task.Shipment==null){outbound++;if(!savedOut){var clone=CityCoreSave.Read(CityCoreSave.Write(s));clone.Simulation.Growth.Zoning.SetSurface((x,z)=>2);for(int k=0;k<40;k++){clone.Advance(.05);s.Advance(.05);}Check(CityCoreSave.Write(s).SequenceEqual(CityCoreSave.Write(clone)),"Empty service outbound save diverged");savedOut=true;break;}}
                else
                {
                    returning++;Check(v.Task.Shipment.kind==CargoKind.Waste&&v.Task.Cargo<=3&&v.Task.citizenId==0,"Service payload or citizen authority wrong");
                    if(positions.TryGetValue(v.id,out Point previous))Check(Point.Distance(previous,s.Transport.Position(v))<=1,"Pickup teleported vehicle to another curb");
                    if(!savedReturn)
                    {
                        int id=v.id,task=v.Task.id;var before=s.Transport.Position(v);int road=s.Transport.Network.Get(v.Current).RoadId;
                        var history=new RoadEditHistory(s.Transport);history.Execute(()=>s.Transport.RemoveRoad(road));Check(v.status==VehicleStatus.Stranded&&v.Task.id==task&&Point.Distance(before,s.Transport.Position(v))<1e-8,"Demolition lost service cargo/location/task");
                        var blocked=CityCoreSave.Read(CityCoreSave.Write(s));blocked.Simulation.Growth.Zoning.SetSurface((x,z)=>2);blocked.Advance(.05);blocked.Validate();Check(blocked.Transport.FindVehicle(id).Task.Cargo==v.Task.Cargo,"Stranded service save lost waste");
                        Check(history.Undo(),"Service road restore failed");s.Advance(.05);Check(v.status==VehicleStatus.Active&&Point.Distance(before,s.Transport.Position(v))<=1,"Restored service car jumped");edited=true;
                        var clone=CityCoreSave.Read(CityCoreSave.Write(s));clone.Simulation.Growth.Zoning.SetSurface((x,z)=>2);for(int k=0;k<80;k++){clone.Advance(.05);s.Advance(.05);Check(CityCoreSave.Write(s).SequenceEqual(CityCoreSave.Write(clone)),"Loaded waste return continuation diverged");}savedReturn=true;transitions++;break;
                    }
                }
            }
            if(!paused&&s.Simulation.Waste.Stored>0)
            {
                var stopped=CityCoreSave.Read(CityCoreSave.Write(s));stopped.Simulation.Growth.Zoning.SetSurface((x,z)=>2);var source=stopped.Entities.Buildings.First(b=>b.Use==LandUse.Power);stopped.Entities.SetAvailability(source.id,true,false);stopped.Simulation.Utilities.Refresh();Check(!stopped.City.Supply(plantId).Complete,"Power failure fixture still supplies processor");long processed=stopped.Simulation.Waste.Processed;stopped.Advance(2);stopped.Validate();Check(stopped.Simulation.Waste.Processed==processed&&stopped.Simulation.Waste.BalanceError==0,"Unpowered treatment destroyed waste");paused=true;
            }
            if(i%20==0){s.Validate();Check(s.Simulation.Waste.BalanceError==0,"Generated/collected/processed waste not conserved");}
        }
        Check(s.City.population>0&&s.City.trade.rawDelivered>0&&s.City.consumption.ConsumedGoods>0&&s.Simulation.Waste.Generated>0&&s.Simulation.Waste.Collected>0&&s.Simulation.Waste.Processed>0&&outbound>0&&returning>0&&savedOut&&savedReturn&&paused&&edited&&transitions>0,"Multi-day city did not complete real waste pickup/return/processing alongside economy");
        var state=s.Simulation.Waste.Snapshot();state.totals.generated=0;Check(s.Simulation.Waste.Generated>0,"Waste snapshot leaked mutable facts");
        // Empty plant cannot bank disposal credit; no inventory may be destroyed by closing.
        bool refused=false;var target=s.Entities.Buildings.FirstOrDefault(b=>b.garbage>0);if(target!=null){var bytes=CityCoreSave.Write(s);try{s.CloseBuilding(target.id);}catch(CityRuleException e){refused=e.Key=="waste.close_not_empty";}Check(refused&&bytes.SequenceEqual(CityCoreSave.Write(s)),"Closing dirty building lost waste or partially changed state");}
        var loaded=CityCoreSave.Read(CityCoreSave.Write(s));loaded.Simulation.Growth.Zoning.SetSurface((x,z)=>2);Check(loaded.Simulation.Design.Waste.Payload==3,"Saved waste rules not frozen");
        Console.WriteLine("WASTE generated="+s.Simulation.Waste.Generated+" collected="+s.Simulation.Waste.Collected+" processed="+s.Simulation.Waste.Processed+" waiting="+s.Simulation.Waste.Waiting+" active="+s.Simulation.Waste.Vehicles);
    }
    static void FiscalTests()
    {
