        Check(cut,"No safe shopping road cut reached");var household=s.Entities.Member(shopper.Task.citizenId).Family;int savings=household.savings;double sales=s.City.consumption.RetailPayments;Point point=s.Transport.Position(shopper);s.Advance(.05);
