        Vehicle carrying=null;for(int i=0;i<5000&&carrying==null;i++){s.Advance(.05);carrying=s.Transport.Vehicles.FirstOrDefault(v=>v.Task.purpose==TransportPurpose.Home&&v.Task.Cargo>0);}
        Check(carrying!=null&&s.City.consumption.RetailPayments>sales,"No paid physical shopping return goods");var member=s.Entities.Member(carrying.Task.citizenId);Check(member.Person.carriedGoods==0&&carrying.Task.Price==0&&carrying.Task.Shipment.kind==CargoKind.Goods,"Two goods owners / return repaid purchase");int goods=carrying.Task.Cargo,consumed=s.City.consumption.ConsumedGoods;var clone=CityCoreSave.Read(CityCoreSave.Write(s));clone.Simulation.Growth.Zoning.SetSurface((x,z)=>2);Check(clone.Simulation.Design.Retail.UnitPrice==60,"Authoring edit reinterpreted saved purchase");
        for(int i=0;i<1000;i++){s.Advance(.05);clone.Advance(.05);}
        s.Validate();clone.Validate();Check(s.City.consumption.ConsumedGoods>=consumed+goods&&s.City.Citizens.Sum(p=>p.wagesPaid)>0,"Goods not consumed after actual home arrival / actual wages not settled");Check(CityCoreSave.Write(s).SequenceEqual(CityCoreSave.Write(clone)),"Shopping/real wages in-flight continuation differs");
        var times=new double[12000];var timer=new System.Diagnostics.Stopwatch();long allocated=GC.GetAllocatedBytesForCurrentThread();int peak=0;for(int i=0;i<times.Length;i++){timer.Restart();s.Advance(.05);timer.Stop();times[i]=timer.Elapsed.TotalMilliseconds;peak=Math.Max(peak,s.Transport.ActiveCount);}allocated=GC.GetAllocatedBytesForCurrentThread()-allocated;s.Validate();Check(s.City.day>=6&&s.City.consumption.ConsumedGoods>0&&s.City.consumption.RetailPayments>0&&s.Entities.Shops.Sum(x=>x.wholesaleCosts)>0,"Multi-day consumer wholesale/retail economy did not operate");double mean=times.Average();Array.Sort(times);System.IO.File.WriteAllText("Temp/RoadCore/growing-retail.csv","population,buildings,roads,day,active_peak,steps,mean_ms,p95_ms,p99_ms,max_ms,allocated_per_step,consumed,retail_payments,wages_paid\n"+string.Join(",",s.City.population,s.City.buildings.Count,s.Transport.Network.RoadCount,s.City.day,peak,times.Length,mean.ToString("F6",System.Globalization.CultureInfo.InvariantCulture),times[11399].ToString("F6",System.Globalization.CultureInfo.InvariantCulture),times[11879].ToString("F6",System.Globalization.CultureInfo.InvariantCulture),times[11999].ToString("F6",System.Globalization.CultureInfo.InvariantCulture),allocated/times.Length,s.City.consumption.ConsumedGoods,s.City.consumption.RetailPayments,s.City.Citizens.Sum(p=>p.wagesPaid)));

