    static void PopulationUtilityTests()
    {
        var s=CityCoreIndustrySession.CreateEmpty();s.Simulation.Growth.Zoning.SetSurface((x,z)=>2);
        int a=s.Transport.AddJunction(new Point(-40,2,0)),b=s.Transport.AddJunction(new Point(40,2,0));s.Transport.AddRoad(a,b,new[]{s.Transport.JunctionPosition(a),s.Transport.JunctionPosition(b)});
        foreach(var lot in new CityBuilding[]{new ResidentialBuilding{x=-24,z=4.5f,housingUnits=2},new IndustrialBuilding{x=0,z=4.5f}}){if(lot is IndustrialBuilding initial){initial.factory.capital=initial.factory.cash=s.Simulation.Design.Production.InitialFactoryCash;}lot.id=s.City.nextBuildingId;Check(s.Simulation.Growth.Zoning.CanPlace(lot),"City test lot invalid");var access=s.Simulation.Growth.Zoning.Entrance(lot);Check(access.HasValue,"City test entrance missing");s.Entities.AddBuilding(lot);s.Transport.RegisterAccess(lot.id,access.Value.drivable,access.Value.distance);}
        s.Advance(121);Check(s.City.population==0&&s.Entities.Members.Count==0,"Migration ignored absent utility supplies");
        foreach(var use in new[]{LandUse.Power,LandUse.Water,LandUse.Sewage}){float x=use==LandUse.Power?16:use==LandUse.Water?24:32;int before=s.City.money;int id=s.Construction.PlaceFacility(use,x,4.5f,0,s.Simulation.Growth.Zoning);Check(s.City.money==before-CityModel.Cost(use)&&s.City.GetBuilding(id).Use==use&&s.City.BuildingAccess(id),"Facility cost/identity/RoadCore access failed");}
        int opening=s.City.money;s.Simulation.Utilities.Build(UtilityKind.Electricity,new Point(-32,2,0),new Point(36,2,0));s.Simulation.Utilities.Build(UtilityKind.Water,new Point(-32,2,0),new Point(36,2,0));
        foreach(float x in new[]{24f,32f})s.Simulation.Utilities.Build(UtilityKind.Water,new Point(x,2,0),new Point(x,2,4.5));
        s.Simulation.Utilities.Refresh();Check(s.City.money<opening&&s.City.Supply(1).Complete&&s.City.Supply(2).Complete&&s.City.WaterDemand>0&&s.City.SewageCapacity>0,"Connected utilities did not actually supply housing/workplace");
        s.Advance(120);Check(s.City.population==7&&s.Entities.Members.Count==7&&s.City.Employed==3&&s.City.Unemployed==1&&s.City.Occupancy(1)==2,"Migration/job ownership is not real entity-derived");Check(s.City.society.families.All(h=>h.rent==0)&&s.City.roads.edges.Count==0&&s.City.traffic.trips.Count==0,"Private housing revived legacy rent/traffic rules");
        int steps=0;while(s.Transport.ActiveCount==0&&steps++<900)s.Advance(.05);Check(s.Transport.ActiveCount>0&&s.City.Citizens.Any(p=>p.tripId!=0),"Automatically employed residents did not make actual trips");var clone=CityCoreSave.Read(CityCoreSave.Write(s));clone.Simulation.Growth.Zoning.SetSurface((x,z)=>2);Check(clone.City.Supply(1).Complete,"Saved pipes/facility supplies not rebuilt");
        var supplied=CityCoreSave.Read(CityCoreSave.Write(s));supplied.Simulation.Growth.Zoning.SetSurface((x,z)=>2);var seed=supplied.City.Factory(2);seed.raw=seed.imported=2;seed.rawCosts+=2*FactoryState.RawPrice;seed.cash-=2*FactoryState.RawPrice;supplied.Advance(20);supplied.Validate();Check(seed.produced==2&&seed.productiveMinutes>0&&supplied.City.Citizens.Any(p=>p.wageCredit>0||p.wagesPaid>0),"Private development attendance failed actual paid processing");
        var rider=s.Transport.Vehicles.First();var exact=s.Transport.Position(rider);s.Transport.SplitRoadAt(1,43.7);Check(Point.Distance(exact,s.Transport.Position(rider))<1e-8,"Population road edit teleported vehicle");clone=CityCoreSave.Read(CityCoreSave.Write(s));clone.Simulation.Growth.Zoning.SetSurface((x,z)=>2);
        bool worked=false;for(int i=0;i<1700;i++){s.Advance(.05);clone.Advance(.05);worked|=s.City.Citizens.Any(p=>p.atWork&&p.workedMinutes>0);}s.Validate();clone.Validate();Check(worked&&s.City.Citizens.Where(p=>p.canWork).All(p=>p.location==1&&p.tripId==0&&!p.atWork),"Residents failed real workplace attendance/return home");Check(s.City.Factory(2).produced==0,"Utility/job presence fabricated raw material production");Check(Convert.ToBase64String(CityCoreSave.Write(s))==Convert.ToBase64String(CityCoreSave.Write(clone)),"Population/utility/in-flight save continuation differs");
        int edge=s.City.utilities.water.edges.First(e=>s.City.utilities.water.Node(e.a).x==32&&s.City.utilities.water.Node(e.b).x==32).id;Check(s.Simulation.Utilities.Remove(UtilityKind.Water,edge),"Pipe removal failed");Check(!s.City.Supply(1).sewage&&s.City.SewageCapacity==0&&s.City.Supply(1).electricity,"Disconnected sewage source still supplied city");CityCoreSave.Read(CityCoreSave.Write(s)).Validate();
    }
    static void R1Tests()
    {
        var s=CityCoreIndustrySession.Create();Check(s.Advance(.023)==0&&s.Simulation.Tick==0,"Partial step advanced time");var clone=CityCoreSave.Read(CityCoreSave.Write(s));Check(clone.Advance(.027)==1&&s.Advance(.027)==1&&s.Simulation.Tick==1&&s.Transport.Clock==.05,"Saved debt / single tick differs");Check(Convert.ToBase64String(CityCoreSave.Write(s))==Convert.ToBase64String(CityCoreSave.Write(clone)),"Saved debt changed complete state");long tick=s.Simulation.Tick;s.Advance(0);Check(tick==s.Simulation.Tick,"Pause advanced clock");bool rejected=false;try{s.Transport.Advance(.1);}catch(InvalidOperationException){rejected=true;}Check(rejected&&s.Simulation.Tick==tick,"Transport advanced city clock independently");rejected=false;try{s.Transport.Step();}catch(InvalidOperationException){rejected=true;}Check(rejected&&s.Simulation.Tick==tick,"Direct city physics step accepted");
        var one=CityCoreIndustrySession.Create();var three=CityCoreIndustrySession.Create();for(int i=0;i<1200;i++)one.Advance(.05);for(int i=0;i<400;i++)three.Advance(.15);Check(one.Simulation.Tick==1200&&three.Simulation.Tick==1200&&one.Transport.Clock==60,"Rate requests lost/duplicated ticks");Check(Convert.ToBase64String(CityCoreSave.Write(one))==Convert.ToBase64String(CityCoreSave.Write(three)),"1x/3x request grouping changed state");
        var indexed=CityCoreIndustrySession.Create();var original=indexed.City.GetBuilding(2);var replacement=new CommercialBuilding{id=2,x=original.x,z=original.z,entranceX=original.entranceX,entranceZ=original.entranceZ};indexed.Entities.ReplaceBuilding(replacement);Check(ReferenceEquals(indexed.City.GetBuilding(2),replacement)&&indexed.Entities.Shops[0]==replacement,"Same-count building replacement stale");indexed.Entities.AddFamily(new Household{id=2,home=3,unit=1,resident=true});indexed.City.Residence(3).housingUnits=2;indexed.City.Factory(1).raw=24;indexed.City.GetBuilding(1).level=2;indexed.City.SyncJobs();var p=new CityResident{id=5,age=30,canWork=true,skill=2,location=3,name="新增工人"};indexed.Entities.AddResident(1,p);var vacant=indexed.City.society.jobEntities.First(j=>j.occupiedCitizenId<0&&j.buildingId==1);indexed.City.AssignJob(p,vacant.id);indexed.Entities.MoveResident(5,2);Check(indexed.Entities.Member(5).Family.id==2&&p.householdId==2&&!indexed.City.society.families[0].people.Contains(p),"Membership move stale");
        indexed.Advance(7);Check(p.atWork&&p.workedMinutes>0&&indexed.Residents.Observe(5).building==1,"New registered resident did not actually commute/work");indexed.Validate();var saved=CityCoreSave.Read(CityCoreSave.Write(indexed));for(int i=0;i<100;i++){indexed.Advance(.05);saved.Advance(.05);}Check(Convert.ToBase64String(CityCoreSave.Write(indexed))==Convert.ToBase64String(CityCoreSave.Write(saved)),"Lifecycle save differs");
        var removal=CityCoreIndustrySession.Create();var idle=new CityResident{id=5,name="待移除",age=20,canWork=true,location=3};removal.Entities.AddResident(1,idle);removal.City.GetBuilding(1).level=2;removal.City.SyncJobs();var job=removal.City.society.jobEntities.First(j=>j.occupiedCitizenId<0&&j.buildingId==1);removal.City.AssignJob(idle,job.id);removal.Entities.RemoveResident(5);Check(removal.Entities.Member(5)==null&&job.occupiedCitizenId==-1,"Removal left person/job references");removal.Advance(.05);var rider=removal.City.Citizens.First(x=>x.tripId>0);int before=removal.Entities.Members.Count;rejected=false;try{removal.Entities.RemoveResident(rider.id);}catch(InvalidOperationException){rejected=true;}Check(rejected&&removal.Entities.Members.Count==before&&rider.tripId>0,"Removed an in-transit person");removal.Validate();
        var unsafeCity=CityCoreIndustrySession.Create();unsafeCity.City.buildings[1]=new CommercialBuilding{id=2};rejected=false;try{unsafeCity.Validate();}catch(InvalidOperationException){rejected=true;}Check(rejected,"Bypassed same-count mutation was silently valid");
        var closing=CityCoreIndustrySession.Create();closing.Advance(.05);var traveler=closing.Transport.Vehicles[0];closing.Entities.SetAvailability(1,true,false);Check(traveler.status==VehicleStatus.Stranded&&closing.City.Job(closing.City.Citizens.First(p2=>p2.tripId>0).jobId)==null,"Availability did not release jobs/interrupt real trip");closing.Validate();
    }
